arguments.evt_summary:
[
  {% for event in vars.evt_fulldetail %}
  {
    {% for key, value in event.items() if value is not none %}
    "{{ key }}": {{ value|tojson }}{% if not loop.last %},{% endif %}
    {% endfor %}
  }{% if not loop.last %},{% endif %}
  {% endfor %}
]

arguments.unique_FoI:
{% set keys = vars.FoInt[0].keys() %}
{
{% set ns = namespace(first=true) %}
{% for key in keys %}
  {% set unique_vals = [] %}
  {% for row in vars.FoInt %}
    {% set val = row.get(key) %}
    {% if val is defined and val is not none and val != "" %}
      {# If the value looks like a JSON array string, parse it #}
      {% if val is string and val.startswith("[") and val.endswith("]") %}
        {% set parsed = val|safe|from_json %}
        {% for p in parsed %}
          {% if p not in unique_vals %}
            {% do unique_vals.append(p) %}
          {% endif %}
        {% endfor %}
      {% else %}
        {% if val not in unique_vals %}
          {% do unique_vals.append(val) %}
        {% endif %}
      {% endif %}
    {% endif %}
  {% endfor %}
  {% if not ns.first %},{% endif %}
  "{{ key }}": {{ unique_vals|tojson }}
  {% set ns.first = false %}
{% endfor %}
}

arguments.FoInt:
[
{% for event in vars.evt_summary -%}
  {
    {%- set pairs = [] -%}
    {%- for key, value in event.items()
          if value is not none
          and value != ""
          and key != "attribute"
          and key != "EventsCount"
          and not (value is string and value.startswith("HOST-")) %}
      {%- set _ = pairs.append('"%s": %s' % (key, value|tojson)) -%}
    {%- endfor -%}
    {{ pairs | join(', ') }}
  }{{ "," if not loop.last }}
{%- endfor %}
]

step_variables._evt_fulldetail:
{%- for event in vars.steps.RunAdvQry.data.events %}
  {%- set parsed = {} %}
  {%- for item in event.dataStr.entry %}
    {%- if item.value is defined and item.value["#text"] is defined %}
      {%- set _ = parsed.update({ item.key: item.value["#text"] }) %}
    {%- else %}
      {%- set _ = parsed.update({ item.key: None }) %}
    {%- endif %}
  {%- endfor %}
  {%- set _ = vars.evt_fulldetail.append(parsed) %}
{%- endfor %}

arguments._temp:
{%- for key, value in vars.item.items() -%}
        {%- if value is defined and value is not none and value != "" -%}
            {%- if key == "srcIpAddr" or key == "destIpAddr" or key == "preNATDestIpAddr" or key == "srcIpAddrV4" or key == "destIpAddrV4" or key == "hostIpAddrV4" -%}
                {%- do vars.ip_addresses.append(value) -%}
            {%- elif key == "uriStem" or key == "infoURL" -%}
                {%- do vars.urls.append(value) -%}
            {%- elif key == "hashMD5" or key == "hashSHA1" or key == "hashSHA256" or key == "hashSHA512" or key == "hashCode" -%}
                {%- do vars.hashes.append(value) -%}
            {%- elif key == "user" or key == "srcUser" or key == "targetUser" -%}
                {%- do vars.users.append(value) -%}
            {%- elif key == "vulnCVEId" or key == "ipsSignatureId" -%}
                {%- do vars.vulnerabilities.append(value) -%}
            {%- elif key == "hostName" or key == "srcName" or key == "destName" or key == "computer" or key == "domain" or key == "targetDomain" -%}
                {%- do vars.domains_hostnames.append(value) -%}
            {%- elif key == "reptDevIpAddr" or key == "filePath" or key == "fileName" or key == "swParam" -%}
                {%- do vars.other_artifacts.append(value) -%}
            {%- endif -%}
        {%- endif -%}
{%- endfor -%}

